    description_ar:
      'ديوان الحماسة - أبي تمام أَبو تَمّام 188 - 231 هـ / 803 - 845 م حبيب بن أوس بن الحارث الطائي، أحد أمراء البيان، ولد بجاسم - من قرى حوران بسورية - ورحل إلى مصر واستقدمه المعتصم إلى بغداد فأجازه وقدمه على شعراء وقته فأقام في العراق ثم ولي بريد الموصل فلم يتم سنتين حتى توفي بها. كان أسمر، طويلاً، فصيحاً، حلو الكلام، فيه تمتمة يسيرة، يحفظ أربعة عشر ألف أرجوزة من أراجيز العرب غير القصائد والمقاطيع. وفي أخبار أبي تمام للصولي: «أنه كان أجش الصوت يصطحب راوية له حسن الصوت فينشد شعره بين يدي الخلفاء والأم...',
