    madhab_en: '',
    description_ar:
      'ديوان الهذليين يعدُّ هذا الديوان من الدواوين الفريدة التي وصلت إلينا، ولو وصلت إلينا بقية الدواوين لكانت ثروة علمية قيّمة، تكشف عن خصائص اجتماعية ولغوية مهمة. وترجع أهمية هذا الديوان إلى أن قبيلة هذيل كانت من قبائل الحجاز المعروفة بفصاحتها وسلامة لغتها من شوائب العجمية؛ لأنها تعيش في وسط الجزيرة العربية، بعيدة عن مناطق الاختلاط بغير العرب، لذلك كان شعر هذه القبيلة موضع اهتمام العلماء والرواة كالشَّيباني والأصمعي، بل اهتم به جلّة الأئمة كالإمام الشافعي.. وقد كان العلماء في جمعهم اللغة والحفاظ على...',
