    description_ar:
      'أحمد علي الكندي المرر اشتهر باسم الكندي وهو اسمه العائلي وينتمي لقبيلة المرر، وهي من قبائل بني ياس. من الشعراء الذين ساهموا في تطوير القصيدة الشعبية والمحافظة على وجودها وجمالها بين الفنون والآداب الشعبية الأخرى. كما ساهم في الكثير من البرامج الاذاعية والتلفزيونية وشارك خارج الدولة في المهرجانات الشعبية لفنون دولة الإمارات. كانت الربابة رفيقة الشاعر عبر الشاشة والاذاعة والأشرطة الصوتية التي انتشرت بين محبي الفنون والآداب الشعبية فقد نجح في التوفيق بين القصيدة والربابة وشدى بأعذب القصائد والألحان...',
