    description_ar:
      'نبذة عن الكتاب: سقط الزند هو الديوان الشعري الذي أبدعه المعري في مطلع حياته قبل رحيله إلى بغداد ، و"سقط" مثلثة السين هي ما سقط من النار عند القدح ، و"الزند" بفتح الزاي وسكون النون هو العود الذي يقدح به النار، أي: المتطاير منه، والكلام على التشبيه أي: قصائده كالشرر المتطاير. وقد قيل في التعليل لهذه التسمية: إنه شبه شعره بالنار، وطبعه بالزند الذي يقدح به النار، وجعله سقطا لأنه أول ما يخرج من الزند، وهذا الشعر هو أول ما سمح به طبعه، وهو في ريعان شبابه.',
